<section class="panel languages-hero"><div class="panel-head"><div><span class="panel-kicker">اللغات والترجمة</span><h2>مركز اللغات الشامل</h2><p>أضف أي لغة ثم ترجم واجهة الموقع من نفس المكان. المقالات والصفحات والتصنيفات تظهر تلقائيًا بحقول هذه اللغة في محرراتها.</p></div><span><?=count($languages)?> لغة</span></div>
<form method="post" action="/admin/languages/save" class="form-grid language-builder"><?=csrf_field()?><input type="hidden" name="id" value="0"><label>كود اللغة<input name="code" placeholder="de" required></label><label>اسم اللغة<input name="name" placeholder="Deutsch" required></label><label>العلم أو رمز الدولة<input name="flag" placeholder="de أو 🇩🇪"></label><label>اتجاه الكتابة<select name="dir"><option value="ltr">LTR</option><option value="rtl">RTL</option></select></label><label>الترتيب<input type="number" name="sort_order" value="50"></label><label class="check"><input type="checkbox" name="enabled" checked> مفعّلة</label><label class="check"><input type="checkbox" name="is_default"> اللغة الأساسية</label><button class="btn btn-primary">إضافة وبدء الترجمة</button></form></section>

<section class="panel"><div class="panel-head"><div><span class="panel-kicker">اللغات الحالية</span><h2>إدارة الظهور والترتيب</h2></div></div><div class="language-admin-list"><?php foreach($languages as $l):?><article class="language-admin-card <?=($editLocale===$l['code'])?'is-editing':''?>"><div class="language-flag-preview"><img class="language-flag-img" src="<?=e(language_flag_src($l['code']))?>" alt=""><a class="btn btn-ghost" href="/admin/languages?edit=<?=rawurlencode($l['code'])?>#translation-center">ترجمة الواجهة</a></div><form method="post" action="/admin/languages/save" class="language-inline-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$l['id']?>"><input name="code" value="<?=e($l['code'])?>"><input name="name" value="<?=e($l['name'])?>"><input name="flag" value="<?=e($l['flag'])?>"><select name="dir"><option value="ltr" <?=$l['dir']==='ltr'?'selected':''?>>LTR</option><option value="rtl" <?=$l['dir']==='rtl'?'selected':''?>>RTL</option></select><input type="number" name="sort_order" value="<?=$l['sort_order']?>"><label class="check"><input type="checkbox" name="enabled" <?=$l['enabled']?'checked':''?>> مفعّلة</label><label class="check"><input type="checkbox" name="is_default" <?=$l['is_default']?'checked':''?>> أساسية</label><button class="btn btn-primary">حفظ</button></form><?php if(!$l['is_default']):?><form method="post" action="/admin/languages/delete" onsubmit="return confirm('حذف اللغة من قائمة الموقع؟ لن نحذف الترجمات القديمة.')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$l['id']?>"><button class="btn btn-danger">حذف</button></form><?php endif;?></article><?php endforeach;?></div></section>

<section class="panel language-coverage-panel"><div class="panel-head"><div><span class="panel-kicker">جاهزية المحتوى</span><h2>تغطية الترجمة لكل لغة</h2><p>الأرقام تقيس النسخ المنشورة فقط؛ المسودات ومواد المراجعة لا تظهر للزائر.</p></div></div><div class="language-coverage-grid"><?php foreach($languages as $l):$s=$languageStats[$l['code']]??['percent'=>0,'articles'=>0,'article_total'=>0,'pages'=>0,'page_total'=>0,'categories'=>0,'category_total'=>0,'podcasts'=>0,'podcast_total'=>0,'khawatir'=>0,'khawatir_total'=>0,'khawatir_categories'=>0,'khawatir_category_total'=>0,'writers'=>0,'writer_total'=>0,'tags'=>0,'tag_total'=>0,'strings'=>0,'string_total'=>0];?><article class="language-coverage-card"><header><strong><?=e(language_name($l['code']))?></strong><b><?=$s['percent']?>%</b></header><div class="language-coverage-bar"><i style="width:<?=$s['percent']?>%"></i></div><dl><div><dt>مقالات</dt><dd><?=$s['articles']?>/<?=$s['article_total']?></dd></div><div><dt>صفحات</dt><dd><?=$s['pages']?>/<?=$s['page_total']?></dd></div><div><dt>تصنيفات</dt><dd><?=$s['categories']?>/<?=$s['category_total']?></dd></div><div><dt>بودكاست</dt><dd><?=$s['podcasts']?>/<?=$s['podcast_total']?></dd></div><div><dt>خواطر</dt><dd><?=$s['khawatir']?>/<?=$s['khawatir_total']?></dd></div><div><dt>تصنيفات الخواطر</dt><dd><?=$s['khawatir_categories']?>/<?=$s['khawatir_category_total']?></dd></div><div><dt>ملفات الكتّاب</dt><dd><?=$s['writers']?>/<?=$s['writer_total']?></dd></div><div><dt>وسوم</dt><dd><?=$s['tags']?>/<?=$s['tag_total']?></dd></div><div><dt>واجهة</dt><dd><?=$s['strings']?>/<?=$s['string_total']?></dd></div></dl></article><?php endforeach;?></div></section>

<section class="panel"><div class="panel-head"><div><span class="panel-kicker">قائمة العمل</span><h2>المحتوى الناقص أو قيد المراجعة</h2></div></div><form class="filters" method="get"><label>اللغة<select name="filter_locale"><?php foreach($languages as $language):?><option value="<?=e($language['code'])?>" <?=$filterLocale===$language['code']?'selected':''?>><?=e($language['name'])?></option><?php endforeach;?></select></label><label>نوع المحتوى<select name="type"><?php foreach(['all'=>'الكل','articles'=>'المقالات','pages'=>'الصفحات','categories'=>'التصنيفات','podcasts'=>'البودكاست','khawatir'=>'الخواطر','khawatir_categories'=>'تصنيفات الخواطر','writers'=>'ملفات الكتّاب','tags'=>'الوسوم'] as $value=>$label):?><option value="<?=$value?>" <?=$filterType===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label>الحالة<select name="state"><?php foreach(['all'=>'الكل','missing'=>'غير مترجم','draft'=>'مسودة','review'=>'تحتاج مراجعة','published'=>'منشور'] as $value=>$label):?><option value="<?=$value?>" <?=$filterState===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><button class="btn btn-primary">تصفية</button></form><div class="table-wrap"><table><thead><tr><th>النوع</th><th>المحتوى العربي</th><th>الحالة</th><th></th></tr></thead><tbody><?php foreach(array_slice($translationQueue,0,250) as $item):?><tr><td><?=e($item['type'])?></td><td><?=e($item['title'])?></td><td><span class="status s-<?=e($item['state'])?>"><?=e($item['state'])?></span></td><td><a href="<?=e($item['url'])?>">تحرير</a></td></tr><?php endforeach;?><?php if(!$translationQueue):?><tr><td colspan="4">لا توجد عناصر مطابقة.</td></tr><?php endif;?></tbody></table></div></section>

<section class="panel translation-center" id="translation-center">
<div class="panel-head"><div><span class="panel-kicker">مركز ترجمة الواجهة</span><h2>ترجمة <?=e(language_name($editLocale))?></h2><p>الحقول الفارغة تستخدم النص الافتراضي مؤقتًا حتى تترجمها. لن تُحذف أو تتغير ترجمات اللغات الأخرى.</p></div><div class="translation-locale-switch"><?php foreach($languages as $l):?><a class="<?=($editLocale===$l['code'])?'active':''?>" href="/admin/languages?edit=<?=rawurlencode($l['code'])?>#translation-center"><?=e(language_name($l['code']))?></a><?php endforeach;?></div></div>
<?php $translatedCount=0; foreach($translationFields as $d){$c=$d['namespace'].'.'.$d['key']; if(trim((string)($translationValues[$c]??''))!=='')$translatedCount++;} $totalTranslationFields=count($translationFields); $translationPercent=$totalTranslationFields?round(($translatedCount/$totalTranslationFields)*100):0; ?>
<div class="translation-toolbar"><label>ابحث داخل حقول الترجمة<input type="search" placeholder="مثال: الهيدر، البحث، المقال..." data-translation-search></label><div class="translation-progress"><span><b><?=$translatedCount?></b> من <b><?=$totalTranslationFields?></b> مترجم</span><div><i style="width:<?=$translationPercent?>%"></i></div><strong><?=$translationPercent?>%</strong></div></div>
<form method="post" action="/admin/languages/translations/save" class="translation-editor-form" data-translation-editor><?=csrf_field()?><input type="hidden" name="locale" value="<?=e($editLocale)?>"><label class="check"><input type="checkbox" name="translation_fallback_enabled" <?=$fallbackEnabled?'checked':''?>> السماح بإظهار العربية عند غياب الترجمة (Fallback عام)</label>
<?php $groups=[]; foreach($translationFields as $d)$groups[$d['group']][]=$d; foreach($groups as $group=>$fields):?><details class="translation-group" open><summary><strong><?=e($group)?></strong><span><?=count($fields)?> حقل</span></summary><div class="translation-field-grid"><?php foreach($fields as $d): $compound=$d['namespace'].'.'.$d['key']; $value=$translationValues[$compound]??'';?><label class="translation-field" data-translation-field><span><?=e($d['label'])?></span><small>الأصل: <?=e($d['fallback'])?></small><?php if(($d['type']??'text')==='textarea'):?><textarea rows="3" name="translations[<?=e($compound)?>]" placeholder="<?=e($d['fallback'])?>"><?=e($value)?></textarea><?php else:?><input name="translations[<?=e($compound)?>]" value="<?=e($value)?>" placeholder="<?=e($d['fallback'])?>"><?php endif;?></label><?php endforeach;?></div></details><?php endforeach;?>
<div class="settings-save-bar"><button class="btn btn-primary">حفظ ترجمة <?=e(language_name($editLocale))?></button></div></form></section>
